/**
 * @suppress
 */
public object FfiConverterTypeAutoEqFetch: FfiConverter<AutoEqFetch, Pointer> {
    internal val handleMap = UniffiHandleMap<AutoEqFetch>()

    override fun lower(value: AutoEqFetch): Pointer {
        return Pointer(handleMap.insert(value))
    }

    override fun lift(value: Pointer): AutoEqFetch {
        return AutoEqFetchImpl(value)
    }

    override fun read(buf: ByteBuffer): AutoEqFetch {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: AutoEqFetch) = 8UL

    override fun write(value: AutoEqFetch, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
