public object FfiConverterTypeLinkListener: FfiConverter<LinkListener, Pointer> {
    internal val handleMap = UniffiHandleMap<LinkListener>()

    override fun lower(value: LinkListener): Pointer {
        return Pointer(handleMap.insert(value))
    }

    override fun lift(value: Pointer): LinkListener {
        return LinkListenerImpl(value)
    }

    override fun read(buf: ByteBuffer): LinkListener {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: LinkListener) = 8UL

    override fun write(value: LinkListener, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}


