/**
 * What `EXT_ALINK_INFO` reports, read once at connect.
 */
data class AlinkInfo (
    /**
     * `none`, `receiver`, `sender`, `repeater`, `fan_out` or `unknown`.
     */
    var `role`: kotlin.String, 
    /**
     * The firmware's role code.
     */
