 * @suppress
 */
public object FfiConverterTypeFilterParams: FfiConverterRustBuffer<FilterParams> {
    override fun read(buf: ByteBuffer): FilterParams {
        return FilterParams(
            FfiConverterUByte.read(buf),
            FfiConverterBoolean.read(buf),
